try {
  await axios.post('http://resume-api:3006/api/v1/internal/n8n/process-resume', {
    resume_id: resumeId,
    action: 'score',
    data: atsScore
  }, {
    headers: { 'X-API-Key': process.env.N8N_API_KEY || 'change-me-secret' }
  });
} catch (e) {
  console.log('ATS save failed (API may not be running):', e.message);
}

// Update resume with improvements
try {
  await axios.post('http://resume-api:3006/api/v1/internal/n8n/process-resume', {
    resume_id: resumeId,
    action: 'improve',
    data: improvements
  }, {
    headers: { 'X-API-Key': process.env.N8N_API_KEY || 'change-me-secret' }
  });
} catch (e) {
  console.log('Improvements save failed (API may not be running):', e.message);
}

return [{
  json: {
    resume_id: resumeId,
    status: 'pipeline_complete',
    ats_score: atsScore,
    improvements: improvements
  }
